{
  "has_event": true,
  "title": "full event title here",
  "Start": "2026-07-27T20:00:00",
  "End": "2026-07-27T21:00:00",
  "Location": "location or empty string"
}

If no event found, return: {"has_event": false, "title": "", "Start": "", "End": "", "Location": ""}

